#pragma once
#ifndef LAYER_NORM_V3_TILING_H
#define LAYER_NORM_V3_TILING_H
#include <cstdint>
constexpr int32_t DEFAULT_BLOCK_M = 128;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 32;
struct LayerNormV3KernelTiling { int32_t M; int32_t N; int32_t blockM; int32_t usedCoreNum; int32_t tasksPerCore; float eps; float invN; };
#endif

