#include "layer_norm_v3_kernel.h"
extern "C" __global__ __aicore__ void layer_norm_v3_custom_fp16(GM_ADDR x,GM_ADDR g,GM_ADDR b,GM_ADDR y,GM_ADDR m,GM_ADDR s,GM_ADDR t){
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    LayerNormV3Kernel<half> k; k.Init(x,g,b,y,m,s,t,&p); k.Process();
}
extern "C" void layer_norm_v3_do_fp16(uint32_t d,void* st,uint8_t* x,uint8_t* g,uint8_t* b,uint8_t* y,uint8_t* m,uint8_t* s,uint8_t* t){
    layer_norm_v3_custom_fp16<<<d,nullptr,st>>>(x,g,b,y,m,s,t);
}

